# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">TÜRKİYE\'DE KARA VE DEMİR YOLU ULAŞIMININ GELİŞİMİ</text>\n  <!-- Kara Yolu -->\n  <rect x="25" y="45" width="315" height="198" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">KARA YOLU AĞI VE ÖZELLİKLERİ</text>\n  <text x="40" y="92" font-size="12" fill="#1e3a8a">• Yolcu ve yük taşımacılığında ~%90 ile 1. sıradadır.</text>\n  <text x="40" y="114" font-size="12" fill="#1e3a8a">• 1950 sonrası kara yolu yapımına ağırlık verilmiştir.</text>\n  <text x="40" y="136" font-size="12" fill="#1e3a8a">• Yeryüzü şekilleri nedeniyle ana koridorlar</text>\n  <text x="50" y="153" font-size="12" font-weight="bold" fill="#1d4ed8">doğu-batı doğrultusunda uzanır (D-100..D-400).</text>\n  <rect x="42" y="168" width="280" height="60" rx="6" fill="#ffffff" stroke="#93c5fd" stroke-width="1.5"/>\n  <text x="182" y="188" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">Önemli Geçit ve Tüneller</text>\n  <text x="182" y="206" text-anchor="middle" font-size="11" fill="#0f172a">Karadeniz: Ovit, Zigana, Kop, Ilgaz, Bolu, Nefise Akçelik</text>\n  <text x="182" y="221" text-anchor="middle" font-size="11" fill="#0f172a">Akdeniz: Çubuk, Sertavul, Gülek, Belen</text>\n  <!-- Demir Yolu -->\n  <rect x="360" y="45" width="315" height="198" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="517" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#92400e">DEMİR YOLU TARİHÇESİ VE YHT</text>\n  <text x="375" y="92" font-size="12" fill="#78350f">• Anadolu\'da ilk hat: İzmir - Aydın (1856-1866).</text>\n  <text x="375" y="114" font-size="12" fill="#78350f">• 1923-1940: Millîleştirme ve "Demir Ağlar" dönemi.</text>\n  <text x="375" y="136" font-size="12" fill="#78350f">• 2009: İlk Yüksek Hızlı Tren (Ankara - Eskişehir).</text>\n  <text x="375" y="156" font-size="12" fill="#78350f">• YHT Hatları: Ankara-Konya, Ankara-İstanbul, Sivas.</text>\n  <rect x="377" y="168" width="280" height="60" rx="6" fill="#ffffff" stroke="#fcd34d" stroke-width="1.5"/>\n  <text x="517" y="188" text-anchor="middle" font-size="11" font-weight="bold" fill="#92400e">Kıtalar Arası Projeler ("Demir İpek Yolu")</text>\n  <text x="517" y="206" text-anchor="middle" font-size="11" fill="#0f172a">• Marmaray (Boğaz tüp geçişi) &amp; Bakü-Tiflis-Kars</text>\n  <text x="517" y="221" text-anchor="middle" font-size="11" fill="#0f172a">• Pekin\'den Londra\'ya kesintisiz demir yolu bağlantısı</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">TÜRKİYE\'DE DENİZ VE HAVA YOLU ULAŞIMI</text>\n  <!-- Deniz Yolu -->\n  <rect x="25" y="45" width="315" height="198" rx="10" fill="#ecfeff" stroke="#0891b2" stroke-width="2"/>\n  <text x="182" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#155e75">DENİZ YOLU VE LİMANLARIMIZ</text>\n  <text x="40" y="92" font-size="12" fill="#164e63">• 1 Temmuz 1926: Kabotaj Kanunu (Millî egemenlik)</text>\n  <text x="40" y="114" font-size="12" fill="#164e63">• Dış ticaret taşımacılığında en ekonomik yoldur.</text>\n  <text x="40" y="136" font-size="12" fill="#164e63">• En fazla yük elleçlenen: Kocaeli, Aliağa, İskenderun,</text>\n  <text x="50" y="153" font-size="12" fill="#164e63">Ambarlı (İstanbul), Mersin, Ceyhan limanları.</text>\n  <rect x="42" y="168" width="280" height="60" rx="6" fill="#ffffff" stroke="#67e8f9" stroke-width="1.5"/>\n  <text x="182" y="188" text-anchor="middle" font-size="11" font-weight="bold" fill="#0e7490">Kruvaziyer ve Ro-Ro Taşımacılığı</text>\n  <text x="182" y="206" text-anchor="middle" font-size="11" fill="#0f172a">• Kruvaziyer: İstanbul, Kuşadası, Bodrum, Antalya</text>\n  <text x="182" y="221" text-anchor="middle" font-size="11" fill="#0f172a">• Ro-Ro: Pendik, Ambarlı, Çeşme, Mersin, Samsun, Trabzon</text>\n  <!-- Hava Yolu -->\n  <rect x="360" y="45" width="315" height="198" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="517" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">HAVA YOLU GELİŞİMİ</text>\n  <text x="375" y="92" font-size="12" fill="#14532d">• 1925: Türk Tayyare Cemiyeti kuruldu.</text>\n  <text x="375" y="114" font-size="12" fill="#14532d">• 1933: İlk ticari uçuşlar (İstanbul-Eskişehir-Ankara).</text>\n  <text x="375" y="136" font-size="12" fill="#14532d">• 1947: İlk yurt dışı seferi (Ankara-İstanbul-Atina).</text>\n  <text x="375" y="156" font-size="12" fill="#14532d">• 2003: Bölgesel Havacılık Projesi ile hızlı büyüme.</text>\n  <rect x="377" y="168" width="280" height="60" rx="6" fill="#ffffff" stroke="#86efac" stroke-width="1.5"/>\n  <text x="517" y="188" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">Modern Havalimanı Yatırımları</text>\n  <text x="517" y="206" text-anchor="middle" font-size="11" fill="#0f172a">• İstanbul Havalimanı (Küresel aktarma merkezi / Hub)</text>\n  <text x="517" y="221" text-anchor="middle" font-size="11" fill="#0f172a">• Deniz dolgusu: Ordu-Giresun ve Rize-Artvin</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">ENERJİ KORİDORU TÜRKİYE: BORU HATLARI AĞI</text>\n  <!-- Sol: Ham Petrol -->\n  <rect x="30" y="48" width="305" height="190" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#991b1b">HAM PETROL BORU HATLARI</text>\n  <text x="45" y="98" font-size="12" fill="#7f1d1d">• Batman - Dörtyol (1967): Türkiye\'nin ilk boru hattı.</text>\n  <text x="45" y="122" font-size="12" fill="#7f1d1d">• Irak - Türkiye (Kerkük - Yumurtalık): 1976\'da</text>\n  <text x="55" y="139" font-size="12" fill="#7f1d1d">işletmeye alınan uluslararası petrol hattı.</text>\n  <text x="45" y="163" font-size="12" fill="#7f1d1d">• Bakü - Tiflis - Ceyhan (BTC): Azerbaycan</text>\n  <text x="55" y="180" font-size="12" fill="#7f1d1d">petrolünü Ceyhan üzerinden dünya pazarına taşır.</text>\n  <rect x="48" y="195" width="270" height="32" rx="6" fill="#fee2e2"/>\n  <text x="183" y="215" text-anchor="middle" font-size="11" font-weight="bold" fill="#991b1b">1974: BOTAŞ (Boru Hatları ile Petrol Taşıma AŞ)</text>\n  <!-- Sag: Dogal Gaz -->\n  <rect x="365" y="48" width="305" height="190" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#6b21a8">DOĞAL GAZ BORU HATLARI</text>\n  <text x="380" y="98" font-size="12" fill="#581c87">• TANAP (Trans Anadolu): Azerbaycan Şahdeniz</text>\n  <text x="390" y="115" font-size="12" fill="#581c87">gazını Türkiye üzerinden Avrupa\'ya (TAP) ulaştırır.</text>\n  <text x="380" y="139" font-size="12" fill="#581c87">• TürkAkım ve Mavi Akım: Rusya\'dan Karadeniz</text>\n  <text x="390" y="156" font-size="12" fill="#581c87">tabanından geçerek Türkiye\'ye ulaşan hatlar.</text>\n  <text x="380" y="180" font-size="12" fill="#581c87">• Bakü-Tiflis-Erzurum (BTE) &amp; Türkiye-İran Hattı.</text>\n  <rect x="383" y="195" width="270" height="32" rx="6" fill="#f3e8ff"/>\n  <text x="518" y="215" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">Stratejik Konum: Doğu-Batı Enerji Köprüsü</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
